/* BODY FIGURE helpers (chat 2, 24 NOV) - copied unchanged from the installed BATTLESPACE (656fe76b): body data + SUIT / suitDefs / xbody + injury tiers.
   His x-ray (mobiGlas art) = PERSONAL ONLY. */

/* copied unchanged from chat 2 crew-body.js so the page stands alone */
/* CREW BODY FIGURE (chat 2, 24 NOV 2026). RAZ: "i want you to use the human figure out of the uplaod i sent you where you can see the veins and nerves etc"
   + "this suit is cumbersome and too big".
   SOURCE: his own mobiGlas HEALTH screenshot (Claude Files\MASTER\mobiGlas health screen.webp), cut to crew-body-xray.png. REAL PIXELS, no redraw, no filters.
   Clean-up: body mask = alpha > 35 (> 70 in the lit haze bottom-left), largest shape, closed 5 px (grow, fill holes, shrink), holes filled; everything outside it cleared (008 label, star dots, haze);
   the 008 label lying on the right thigh replaced by the same thigh real pixels 12 rows above.
   Scaled down to 128 x 260. FIGURE = CIG GAME ART (Star Citizen mobiGlas): PERSONAL / ORG PAGES ONLY, NOT FOR SALE COPIES.
   X = x-ray picture, S = body silhouette mask, Z = 6 zone masks, ZC = zone centres (px of this size).
   ZONES cut on the silhouette (player's RIGHT = IMAGE LEFT, the figure faces the viewer):
   - NECK: rows above where the outline first widens past 1.6 x the head width, plus a shallow arc under the chin.
   - ARMS: from each armpit (first row where an arm piece splits off the torso piece) everything outside the torso piece; above the armpit the
     shoulder cut rises from the armpit gap tilting outward 15 deg, so the shoulder (deltoid) goes with the arm and the trapezius stays torso.
   - HIPS: crotch = first row where the body centre line leaves the body; a V cut rises from it to each outer hip (4.5 % of the height).
     Below the crotch the piece next to the gap is the leg, pieces further out are the hands.
   - TORSO (chest field) = the rest. */
window.CREW_SUIT = window.CREW_BODY = { w: 128, h: 260,
X: "data:image/png;base64,",
S: "data:image/png;base64,",
Z: {
head: "data:image/png;base64,",
chest: "data:image/png;base64,",
r_arm: "data:image/png;base64,",
l_arm: "data:image/png;base64,",
r_leg: "data:image/png;base64,",
l_leg: "data:image/png;base64," },
ZC: {head: [64.4, 22.8], chest: [63.6, 83.6], r_arm: [16.7, 99.5], l_arm: [111.7, 102.5], r_leg: [43.0, 182.0], l_leg: [90.8, 182.0]} };

/* 24 NOV: male / female figure from the character chosen in TOC setup (RAZ). 'cmdglas-body-type' = male | female (or ?body=female).
   The female figure needs its own source picture (window.CREW_BODY_FEMALE); until it exists the male figure is used. */
const BODY_TYPE = (() => { try { return new URLSearchParams(location.search).get('body') || localStorage.getItem('cmdglas-body-type') || 'male'; } catch (e) { return 'male'; } })();
const SUIT = () => (BODY_TYPE === 'female' && window.CREW_BODY_FEMALE) || window.CREW_BODY || window.CREW_SUIT || null;
/* masks once per drawing (ids shared, same content): silhouette + 6 zones */
const suitDefs = () => { const S = SUIT(); if (!S) return ''; const mk = (id, href) => `<mask id="${id}" maskUnits="userSpaceOnUse" maskContentUnits="userSpaceOnUse" x="0" y="0" width="${S.w}" height="${S.h}"><image href="${href}" width="${S.w}" height="${S.h}"/></mask>`;
  return `<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs><filter id="bsInjGlow" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="1.6" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>${mk('bsXlum', S.X)}${mk('bsBodyS', S.S)}${Object.keys(S.Z).map(k => mk('bsZ_' + k, S.Z[k])).join('')}</defs></svg>`; };
/* x-ray body: x = centre, y = top, h = height. st = '' | 'downed' | 'dead'; I = injuries */
function xbody(x, y, h, st, I) { const S = SUIT(); if (!S) return ''; const k = h / S.h, w = S.w * k;
  const tint = injAny(I) && st !== 'dead' ? Object.keys(INJ_REG).map(z => { const t = injTier(I[z]); return t ? `<g mask="url(#bsZ_${z})"><rect class="inj inj${t}" width="${S.w}" height="${S.h}" fill="${INJ_COL[t]}" mask="url(#bsXlum)"/></g>` : ''; }).join('') : '';
  const dead = st === 'dead' ? `<rect width="${S.w}" height="${S.h}" fill="#ff1f3d" opacity=".55" mask="url(#bsBodyS)"/>` : '';
  const xo = st === 'dead' ? .75 : st === 'downed' ? .5 : 1, xf = st === 'dead' ? 'filter:grayscale(1);' : '';
  return `<g transform="translate(${(x - w / 2).toFixed(2)} ${y.toFixed(2)}) scale(${k.toFixed(4)})" style="isolation:isolate">${dead}<image href="${S.X}" width="${S.w}" height="${S.h}" opacity="${xo}" style="${xf}"/><g filter="url(#bsInjGlow)">${tint}</g></g>`; }
const INJ_COL = { 1: '#ff1f3d', 2: '#ff8a00', 3: '#ffe100' };
const INJ_REG = { head: 1, chest: 1, r_arm: 1, l_arm: 1, r_leg: 1, l_leg: 1 }; /* the 6 zones (masks in crew-body.js) */
const INJ_OFF = { head: [30, -4], chest: [0, 26], r_arm: [-34, -14], l_arm: [34, -14], r_leg: [-30, 14], l_leg: [30, 14] }; /* badge offset from the zone centre (body px): limbs' numbers sit beside the limb */
const injTier = v => v === 1 || v === 2 || v === 3 ? v : null;
const injAny = I => !!I && Object.keys(INJ_REG).some(k => injTier(I[k]));
window.xbody = xbody; window.suitDefs = suitDefs;
